document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,t="info"){return`\n      <div class="insight-card ${t}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const t=document.getElementById("construction-form"),i=document.getElementById("construction-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const a=document.getElementById("company-type").value,o=parseInt(document.getElementById("initial-employees").value),r=parseFloat(document.getElementById("equipment-cost").value),l=parseFloat(document.getElementById("office-cost").value),c=parseFloat(document.getElementById("working-capital").value),d=parseFloat(document.getElementById("avg-project-value").value),p=parseFloat(document.getElementById("profit-margin").value),u=parseFloat(document.getElementById("high-season-projects").value),v=parseFloat(document.getElementById("low-season-projects").value),m=parseFloat(document.getElementById("high-season-months").value),g=parseFloat(document.getElementById("staff-costs").value),f=parseFloat(document.getElementById("rent-costs").value),y=parseFloat(document.getElementById("transport-costs").value),w=parseFloat(document.getElementById("other-expenses").value);if(o<=0||d<=0||p<=0||u<=0||v<=0)return i.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const $=r+l+c,h=12-m,b=u*d,I=v*d,E=b*m,k=I*h,B=E+k,F=p/100,j=B*F,P=g+f+y+w,C=12*P,x=j-C,M=x/12,L=x/B*100,A=$/x,D=x/$*100,R=B/o,S=x/o,O=(u*m+v*h)/12,T=j/12/O,q={"small-renovation":"Small Renovation Company",residential:"Residential Construction",commercial:"Commercial Construction","general-contractor":"General Contractor"};let V="info";x<0?V="warning":L>20&&(V="success");let G="info";D<25?G="warning":D>40&&(G="success");let U="info";R<5e4?U="warning":R>15e4&&(U="success"),i.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🏗️ Construction Company Business Plan Analysis</h3>\n          <div class="company-type-indicator">\n            <span class="company-type-badge">${q[a]}</span>\n          </div>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n($),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(M),`Net margin: ${e(L)}`,V)}\n            ${s("⏱️ Payback Period",`${A.toFixed(1)} years`,`ROI: ${e(D)}`,A<=3?"success":"warning")}\n            ${s("👥 Revenue per Employee",n(R),"Staff efficiency",U)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Equipment & machinery</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Office & warehouse setup</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses & working capital</span>\n                  <span>${n(c)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n($)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>High season (${m} months × ${u} projects)</span>\n                  <span>${n(E)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Low season (${h} months × ${v} projects)</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Gross profit (${e(p)} margin)</span>\n                  <span>${n(j)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Revenue</strong></span>\n                  <span><strong>${n(B)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Staff payroll (${o} employees)</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Office & warehouse rent</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Transportation & equipment maintenance</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other operating expenses</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(P)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>📊 Project Efficiency</h6>\n              <div class="metric-subtitle">\n                Average project value: <strong>${n(d)}</strong><br>\n                Profit per project: <strong>${n(T)}</strong><br>\n                Projects per month: <strong>${O.toFixed(1)} units</strong>\n              </div>\n            </div>\n            <div class="insight-card ${x>0?"success":"warning"}">\n              <h6>📈 Seasonal Analysis</h6>\n              <div class="metric-subtitle">\n                High season: <strong>${n(b)}/month</strong><br>\n                Low season: <strong>${n(I)}/month</strong><br>\n                Variance: <strong>${e((b-I)/I*100)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${M>0?"success":"warning"}">\n              <h6>💰 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual net profit: <strong>${n(x)}</strong><br>\n                Weekly profit: <strong>${n(x/52)}</strong><br>\n                Profit per employee: <strong>${n(S)}/year</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>🎯 Growth Potential</h6>\n              <div class="metric-subtitle">\n                +1 project/month: <strong>+${n(d*F*12)}/year</strong><br>\n                +5% margin increase: <strong>+${n(.05*B)}/year</strong><br>\n                50% team expansion: <strong>potential +${e(50)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${L<15?"<li>⚠️ Low profitability. Consider increasing margins or reducing costs.</li>":""}\n              ${R<75e3?"<li>📍 Low productivity. Improve work efficiency or increase pricing.</li>":""}\n              ${A>4?"<li>⏰ Long payback period. Optimize startup costs or increase profitability.</li>":""}\n              ${O<2?"<li>📈 Few projects. Intensify marketing and client acquisition.</li>":""}\n              ${L>25?"<li>🎉 Excellent profitability! Consider business expansion.</li>":""}\n              <li>🏆 Specialize in profitable niches: luxury homes, commercial real estate.</li>\n              <li>📊 Implement CRM system for project and client management.</li>\n              <li>🤝 Develop long-term partnerships with material suppliers.</li>\n              <li>⭐ Invest in reputation: project portfolio, client testimonials, certifications.</li>\n              <li>💡 Adopt new technologies: BIM modeling, energy-efficient solutions.</li>\n              <li>📈 Diversify services: design-build, engineering, maintenance contracts.</li>\n              <li>🎯 Participate in government tenders for stable project pipeline.</li>\n              <li>🏗️ Invest in modern equipment to increase productivity.</li>\n              <li>📚 Continuously train staff on new technologies and standards.</li>\n              <li>💰 Create reserve fund to cover seasonal fluctuations.</li>\n              <li>🔄 Implement lean construction principles to reduce waste.</li>\n              <li>📱 Use project management software for better coordination.</li>\n              <li>🛡️ Maintain comprehensive insurance coverage for all projects.</li>\n              <li>🎨 Offer design services to increase project value and margins.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.constructionBusinessData={"Company Type":q[a],"Number of Employees":o,"Total Investment ($)":$,"Annual Revenue ($)":B,"Gross Profit ($)":j,"Annual Expenses ($)":C,"Annual Net Profit ($)":x,"Monthly Profit ($)":M,"Gross Margin (%)":p,"Net Margin (%)":L,"Annual ROI (%)":D,"Payback Period (years)":A,"Revenue per Employee ($)":R,"Profit per Employee ($)":S,"Average Project Value ($)":d,"Projects per Month":O}}),window.downloadCSV=function(){if(!window.constructionBusinessData)return;const n=Object.entries(window.constructionBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="construction-business-plan.csv",s.click()}});